window.DGNL_DE_MON["l13"] = {"id": "l13", "ten": "Đề thi thử số 13", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "Cung kiếm ra tay, thiên hạ đổ dồn hai mắt lại<br>Triều đình cử mục, anh hùng chỉ có một ngươi thôi. (Nguyễn Khuyến)<br>Biện pháp tu từ chỉ có trong câu thứ hai là gì?", "choices": ["Chơi chữ.", "Đối.", "Nhân hoá.", "Nói quá."], "correctIndex": 0, "explain": "<b>Câu 1: Chọn A</b> <b>Giải thích:</b> Trong câu &quot;anh hùng chỉ có một ngươi thôi&quot;, từ <b>&quot;ngươi&quot;</b> vừa là đại từ chỉ người (anh), vừa gợi liên tưởng đến con ngươi trong đôi mắt (kết nối với hình ảnh &quot;đổ dồn hai mắt&quot; ở câu trên). Đây là phép <b>chơi chữ</b> đồng âm."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>CHUYỆN ĐỜI<br>(Khuyết danh)<br>Vất vất vơ vơ cũng nực cười<br>Cắm cắm cúi cúi có hơn ai<br>Nay còn chị chị anh anh đó<br>Mai đã ông ông mụ mụ rồi<br>(Dương Quảng Hàm, Việt Nam văn học sử yếu, tr.123)<br>Biện pháp tu từ nào không được sử dụng trong bài thơ trên?", "choices": ["Chơi chữ.", "Điệp từ.", "Nghịch ngữ.", "Đối."], "correctIndex": 2, "explain": "<b>Câu 2: Chọn C</b> <b>Giải thích:</b> Bài thơ sử dụng chơi chữ (chị chị anh anh), điệp từ (vất vất vơ vơ, cắm cắm cúi cúi) và phép đối (Nay còn... / Mai đã...). Biện pháp <b>nhân hóa</b> không xuất hiện trong văn bản này"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Thảng mảng nhàn chơi sách miễn yên.</i><br><i>Nhìn xem cảnh vật khác phàm gian.</i><br><i>Phất phơ gió lay phiến trúc,</i><br><i>Thánh thót mưa lọt cửa lan.</i><br><i>Rượu chuốc kim bôi mùi mới tỉnh,</i><br><i>Hương thiên thạch đỉnh khói chưa tàn.</i><br><i>Câu thanh nhàn đọc qua ngày tháng,</i><br><i>Tháp cửa nào cho tục khách han.</i><br>(Bài 50, Bạch Vân quốc ngữ thi tập, Nguyễn Bỉnh Khiêm)<br>Từ “han” trong bài thơ trên có nghĩa là gì?", "choices": ["Thăm hỏi.", "Đến chơi.", "Bước vào.", "Đàm luận."], "correctIndex": 0, "explain": "<b>Câu 3: Chọn A</b> <b>Giải thích:</b> Trong tiếng Việt cổ và ngữ cảnh văn chương trung đại (Nguyễn Bỉnh Khiêm), từ <b>&quot;han&quot;</b> có nghĩa là <b>thăm hỏi</b>, hỏi han"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><b>Nhắn nhủ</b><br>Những đêm êm ấm trăng hôn lá,<br>Nhạc nổi từng mây hoa đẫm hương,<br>Hồn mộng lên thăm mà có muộn<br>Đừng quên đây vốn khách đa mang.<br>(Quách Tấn)<br>Đâu là nhận định đúng về cảnh vật thiên nhiên trong câu thơ trên?", "choices": ["Cảnh thiên nhiên hiện lên dữ dội, khoáng đạt, mang vẻ hùng vĩ của núi rừng hoang sơ.", "Cảnh thiên nhiên quấn quýt, được cảm nhận bằng nhiều giác quan, mang vẻ đẹp nên thơ.", "Cảnh thiên nhiên gợi sự hiu quạnh, tàn úa, phản chiếu nỗi buồn cô đơn của con người.", "Cảnh thiên nhiên hiện lên huyền áo, các sự vật đang hợp thể tạo thành một khối."], "correctIndex": 1, "explain": "<b>Câu 4: Chọn B</b> <b>Giải thích:</b> Các hình ảnh &quot;trăng hôn lá&quot;, &quot;hoa đẫm hương&quot; thể hiện sự giao hòa, quấn quýt của thiên nhiên qua thị giác, xúc giác và khứu giác, mang vẻ đẹp lãng mạn, nên thơ."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Trải mấy lớp tiền vương dựng </i><b><i>mở</i></b><i>,</i><br><i>Bốn ngàn năm giãi gió dầm mưa,</i><br><i>Biết bao công của người xưa,</i><br><i>Gang sông, tấc núi, dạ thưa, ruột tằm.</i><br>(Ái Quốc, Phan Bội Châu)<br>Từ in đậm hiệp vần với từ nào?", "choices": ["mưa.", "gió.", "giãi.", "dầm."], "correctIndex": 1, "explain": "<b>Câu 5: Chọn B</b> <b>Giải thích:</b> Đây là thể thơ song thất lục bát. Từ in đậm &quot;mưa&quot; (cuối câu lục) hiệp vần với từ <b>&quot;gió&quot;</b> (trong câu thất tiếp theo: &quot;giãi gió dầm mưa&quot;) theo luật trắc - bằng của thể thơ này."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>LÊ TƯƠNG DỰC, mơ mộng - Cửu Trùng Đài?<br>LÊ AN - Cửu Trùng Đài! Tâu Hoàng thượng, y khai trước mặt hạ thần là đành chết chứ không chịu làm.<br>VUA và KIM PHƯỢNG, kinh ngạc - Không chịu làm?<br>LÊ AN - Thần đã dỗ dành, dọa nạt nhưng y vẫn chấp nê, y còn nói..<br>LÊ TƯƠNG DỰC - Nó nói sao? Cho ngươi cứ thực tâu bày.<br>LÊ AN - Tâu Hoàng thượng, y nói, nếu là đời vua Hồng Đức, y không ngại gì trổ hết tài năng xây một tòa cung điện nguy nga; còn Hoàng thượng, là.. hôn quân, bạo chúa, xin Hoàng thượng tha chết cho hạ thần (người run bắn lên). Vì thế nên y nhất định không giúp Hoàng thượng xây đài.<br>(Nguyễn Huy Tưởng, Vũ Như Tô)<br>Qua lời thuật lại của Lê An, nhân vật Vũ Như Tô hiện lên với đặc điểm nổi bật nào sau đây?", "choices": ["Là người nóng nảy, thiếu khôn khéo trong cách ứng xử với quyền lực.", "Là người tài, có khí phách và giữ vững nguyên tắc trước cường quyền.", "Là người kiêu ngạo, coi thường triều đình và mọi người xung quanh.", "Là người mơ mộng viển vông, chỉ biết theo đuổi lí tưởng cá nhân."], "correctIndex": 1, "explain": "<b>Câu 6: Chọn B</b> <b>Giải thích:</b> Qua lời thuật, Vũ Như Tô sẵn sàng chết chứ không xây đài cho &quot;hôn quân, bạo chúa&quot; nhưng lại sẵn lòng trổ tài cho vua sáng (đời Hồng Đức). Điều này cho thấy ông là người có <b>tài năng, khí phách</b> và giữ vững nguyên tắc đạo đức."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><table class=\"bang-de\"><tr><td>“Tiếp sau đó, là một cuộc săn đuổi trên không, với một tốc độ kinh khủng qua vòm trời và qua vành đất. Những mũi tên của Ravana bay xuống như mưa; lão cúi xuống tiêu diệt hết cả mọi sinh vật trong cõi trần. Nhưng những mũi tên của Rama đã phân tán, bẻ gãy, và làm vô hiệu những mũi tên của Ravana. Những vị thần theo dõi cuộc săn đuổi này cũng hoảng hốt. Đến lúc này những mũi tên của Ravana bắn ngã những con ngựa của Rama và đâm thủng trái tim của Matali. Thần đánh xe ngã xuống. Rama dừng lại một phút vì đau xót, và chưa biết mình sẽ làm gì đây. Nhưng rồi chàng bình tĩnh lại và tiếp tục tấn công. Đúng lúc đó, người ta thấy thần đại bàng Garuda đậu trên trụ cờ của Rama và các vị thần đang theo dõi cảm thấy đó là một điềm lành.”<br>(Trích sử thi Ramayana)</td><td>Pê-nê-lốp thận trọng đáp:<br>- [..] Vậy thì, Ơ-ri-clê ! Già hãy khiêng chiếc giường chắc chắn ra khỏi gian phòng vách tường kiên cố do chính tay Uy-lít-xơ xây lên, rồi lấy da cừu, chăn và vải đẹp trải lên giường.<br>Nàng nói vậy để thử chồng, nhưng Uy-lít-xơ bỗng giật mình nói với người vợ thận trọng:<br>- Nàng ơi, nàng vừa nói một điều làm cho tôi chột dạ. Ai đã xê dịch giường tôi đi chỗ khác vậy? Nếu không có thần giúp đỡ thì dù là người tài giỏi nhất cũng khó lòng làm được việc này. [..] Đây là một chiếc giường kì lạ, kiến trúc có điểm rất đặc biệt, do chính tay tôi làm lấy chứ chẳng phải ai […]<br>Người nói vậy, và Pê-nê-lốp bủn rủn cả chân tay, nàng thấy Uy-lít-xơ tả đúng mười mươi sự thực. Nàng bèn chạy ngay lại, nước mắt chan hòa, ôm lấy cổ chồng, hôn lên trán chồng..<br>- Uy-lít-xơ! Xin chàng chớ giận thiếp, vì từ xưa nay chàng vẫn là người nổi tiếng khôn ngoan. Ôi! Thần linh đã dành cho hai ta một số phận xiết bao cay đắng..<br>(Trích Ô-đi-xê, sử thi Hy Lạp)</td></tr></table><br>Đâu là phương án nêu được điểm tương đồng của hai hình tượng anh hùng trong các ngữ liệu trên?", "choices": ["Đều được đặt trong tình huống thử thách, qua đó bộc lộ bản lĩnh làm chủ hoàn cảnh và phẩm chất khác thường của người anh hùng.", "Đều được khắc họa trong sự đối diện với biến cố bất ngờ, qua đó nhấn mạnh sức mạnh chiến đấu như phẩm chất quan trọng của người anh hùng.", "Đều có sự hiện diện của yếu tố thần linh, qua đó cho thấy số phận nhân vật được quyết định chủ yếu bởi quyền năng siêu nhiên.", "Đều được đặt trong quan hệ với người đồng hành thân thiết, qua đó làm nổi bật tình nghĩa cá nhân hơn là tầm vóc sử thi."], "correctIndex": 0, "explain": "<b>Câu 7: Chọn A</b> <b>Giải thích:</b> Cả Rama (chiến đấu với Ravana) và Uy-lít-xơ (vượt qua thử thách chiếc giường của vợ) đều đặt trong tình huống cam go để bộc lộ <b>bản lĩnh và phẩm chất</b> phi thường của người anh hùng sử thi."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Kẻ đắp chăn bông kẻ lạnh lùng,</i><br><i>Chém cha cái kiếp lấy chồng chung.</i><br><i>Năm chừng mười hoạ hay chăng chớ,</i><br><i>Một tháng đôi lần có cũng không.</i><br><i>Cố đấm ăn xôi xôi lại hỏng,</i><br><i>Cầm bằng làm mướn mướn không công.</i><br><i>Nỗi này ví biết dường này nhỉ,</i><br><i>Thời trước thôi đành ở vậy xong.</i><br>(Lấy chồng chung, Hồ Xuân Hương)<br>Đâu không phải là tác dụng của việc sử dụng thành ngữ trong bài thơ trên?", "choices": ["Gợi sắc thái dân gian, khẩu ngữ, làm cho lời thơ gần với lời than trách đời thường.", "Diễn tả nỗi cay đắng của người phụ nữ khi cố níu giữ chút quyền lợi nhưng cuối cùng vẫn bẽ bàng, thiệt thòi.", "Góp phần tạo giọng điệu chua chát, tự giễu, qua đó bộc lộ ý thức phản kháng trước cảnh lấy chồng chung.", "Thể hiện thái độ cam lòng, bằng lòng của người phụ nữ với thân phận làm lẽ trong chế độ hôn nhân xưa."], "correctIndex": 3, "explain": "<b>Câu 8: Chọn D</b> <b>Giải thích:</b> Các thành ngữ &quot;cố đấm ăn xôi&quot;, &quot;làm mướn không công&quot; nhấn mạnh sự chua chát, bẽ bàng và phản kháng, không phải thể hiện sự <b>cam chịu, bằng lòng</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Con thuyền đi qua</i><br><i>để lại sóng</i><br><i>Đoàn tàu đi qua</i><br><i>để lại tiếng</i><br><i>Đoàn người đi qua</i><br><i>để lại bóng</i><br><i>Tôi không đi qua tôi</i><br><i>để lại gì?</i><br>(Không đề, Văn Cao)<br>Đâu là thông điệp phù hợp nhất có thể rút ra từ bài thơ trên?", "choices": ["Con người cần tự ý thức về sự hiện diện của mình trong đời sống, từ đó sống sao cho có ý nghĩa và để lại những giá trị riêng.", "Mỗi sự vật khi đi qua cuộc đời đều để lại một dấu vết nhất định, vì vậy con người cần biết trân trọng mọi kỉ niệm đã qua.", "Con người chỉ thật sự có giá trị khi những việc mình làm tạo được ảnh hưởng rõ rệt đối với cộng đồng và được người khác ghi nhớ.", "Thời gian trôi qua không bao giờ trở lại, nên con người cần sống chậm hơn để cảm nhận đầy đủ vẻ đẹp của hiện tại."], "correctIndex": 0, "explain": "<b>Câu 9: Chọn A</b> <b>Giải thích:</b> Bài thơ đặt ra câu hỏi &quot;Tôi không đi qua tôi / để lại gì?&quot; nhằm thức tỉnh con người về <b>ý thức sự hiện diện</b> và giá trị của bản thân trong cuộc đời."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Người dân xóm 7, xã Quang Minh kể: phải tới hàng trăm đêm ông Trần Văn Ngô lang thang trên đoạn đường làng khúc khuỷu, vòng vo, mà vẫn ra đúng được cái nghĩa địa ông cần tới. Ông ra để khóc con.</i><br><i>Hai mắt ông ngập trong bóng tối, đôi chân lần tìm, bàn tay chìa lên phía trước quờ quạng không gian. Bản năng lần đường của người mù thật kì lạ. Người dân xóm 7, xã Quang Minh kể: phải tới hàng trăm đêm ông Trần Văn Ngô lang thang trên đoạn đường làng khúc khuỷu, vòng vo, mà vẫn ra đúng được cái nghĩa địa ông cần tới. Ông ra để khóc con. Tiếng khóc của ông đêm đêm nghe xé xót, não lòng. Tiếng khóc bay theo gió âm âm, u u vọng về làng. Ông khóc gọi hồn đứa con đang ngủ với đất. Đứa con không nghe thấy tiếng ông. Ông khóc những đứa còn sống, nhưng không được sống kiếp “con người”.</i><br>(Ba đời hoạ da cam, Minh Chuyên)<br>Đâu là câu văn chứa yếu tố phi hư cấu rõ nhất trong đoạn trích trên?", "choices": ["“Người dân xóm 7, xã Quang Minh kể: phải tới hàng trăm đêm ông Trần Văn Ngô lang thang trên đoạn đường làng khúc khuỷu, vòng vo, mà vẫn ra đúng được cái nghĩa địa ông cần tới.”", "“Hai mắt ông ngập trong bóng tối, đôi chân lần tìm, bàn tay chìa lên phía trước quờ quạng không gian.”", "“Tiếng khóc của ông đêm đêm nghe xé xót, não lòng.”", "“Ông khóc gọi hồn đứa con đang ngủ với đất.”"], "correctIndex": 0, "explain": "<b>Câu 10: Chọn A</b> <b>Giải thích:</b> Câu này chứa các thông tin cụ thể về địa danh (xóm 7, xã Quang Minh) và tên người thật (ông Trần Văn Ngô), đây là những yếu tố <b>phi hư cấu</b> (xác thực) rõ rệt nhất."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Vũ trụ nội mạc phi phận sự,<br>Ông Hi Văn tài bộ đã vào lồng.<br>Khi Thủ khoa, khi Tham tán, khi Tổng đốc Đông,<br>Gồm thao lược đã nên tay ngất ngưởng.<br>Lúc bình Tây, cờ đại tướng,<br>Có khi về Phủ doãn Thừa Thiên.”<br>(Bài ca ngất ngưỡng, Nguyễn Công Trứ)<br>Đâu là nhận định <b>không</b> đúng về đoạn thơ trên?", "choices": ["Đoạn thơ thể hiện ý thức mạnh mẽ của Nguyễn Công Trứ về tài năng, công danh và vai trò nhập thế của bản thân.", "Các chức danh như “Thủ khoa”, “Tham tán”, “Tổng đốc Đông”, “Phủ doãn Thừa Thiên” góp phần khắc họa con người từng trải, có nhiều thành tựu chốn quan trường.", "Giọng điệu đoạn thơ mang sắc thái tự hào, ngang tàng, cho thấy cái tôi cá nhân muốn khẳng định bản lĩnh giữa cuộc đời.", "Đoạn thơ thừa nhận sự tầm thường của công danh và lựa chọn lánh đời để thoát khỏi vòng danh lợi."], "correctIndex": 3, "explain": "<b>Câu 11: Chọn D</b> <b>Giải thích:</b> Đoạn thơ liệt kê hàng loạt chiến công và chức tước để thể hiện cái tôi <b>&quot;ngất ngưỡng&quot;</b>, tự hào về công danh, chứ không phải &quot;lánh đời&quot; hay &quot;thừa nhận sự tầm thường&quot; của công danh"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“<i>Nàng rằng: “Nghĩa trọng nghìn non,</i><br><i>Lâm Chuy người cũ, chàng còn nhớ không?</i><br><i>Sâm, Thương chẳng vẹn chữ tòng,</i><br><i>Tại ai, há dám phụ lòng cố nhân”</i><br>(Truyện Kiều, Nguyễn Du)<br>Biện pháp tu từ chơi chữ trong tác phẩm dựa trên cơ sở nào?", "choices": ["Dùng những từ gần nghĩa.", "Dùng từ đồng nghĩa.", "Dùng từ trái nghĩa.", "Dùng từ có cùng âm đầu."], "correctIndex": 1, "explain": "<b>Câu 12: Chọn B</b> <b>Giải thích:</b> Trong Truyện Kiều, các biện pháp chơi chữ thường dựa trên việc sử dụng <b>từ đồng nghĩa</b> hoặc các điển tích, điển cố có ý nghĩa tương đương để tạo ra nhiều tầng nghĩa."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Văn học Việt Nam gồm mấy bộ phận lớn?", "choices": ["Hai bộ phận lớn: văn học truyền miệng và văn học bác học.", "Hai bộ phận lớn: văn học dân gian và văn học viết.", "Ba bộ phận lớn: văn học dân gian, văn học trung đại và văn học hiện đại.", "Bốn bộ phận lớn: văn học dân gian, văn học chữ Hán, văn học chữ Nôm và văn học chữ Quốc ngữ."], "correctIndex": 1, "explain": "<b>Câu 13: Chọn B</b> <b>Giải thích:</b> Theo lịch sử văn học, văn học Việt Nam gồm hai bộ phận lớn là <b>văn học dân gian</b> (truyền miệng) và <b>văn học viết</b>."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Ngay cả những tác giả lớn, cũng có thể viết rất nhiều tác phẩm không lấy gì làm đặc biệt trước khi sở hữu một tác phẩm thực sự.<br>Câu trên mắc lỗi gì?", "choices": ["Sai logic.", "Sai dùng từ.", "Sai quy chiếu.", "Sai ngữ pháp."], "correctIndex": 3, "explain": "<b>Câu 14: Chọn D</b> <b>Giải thích:</b> Câu này mắc lỗi <b>ngữ pháp</b> (cách sắp xếp các thành phần câu làm câu trở nên lủng củng và không rõ ý)"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Câu nào sau đây không phải là câu mơ hồ?", "choices": ["Chúng ta giữ nguyên âm đầu.", "Tay không đánh người.", "Con trâu cái bụng tròn to mọng.", "Những cô gái đi chân trần trên cát."], "correctIndex": 3, "explain": "<b>Câu 15: Chọn D</b> <b>Giải thích:</b> Câu &quot;Những cô gái đi chân trần trên cát&quot; có cấu trúc rõ ràng, đơn nghĩa. Các câu còn lại đều có thể hiểu theo nhiều cách (ví dụ: &quot;Tay không đánh người&quot; có thể là tay không có vũ khí, hoặc hành động đánh người bằng tay)"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Phương án nào chứa những từ đúng chính tả?", "choices": ["xông xáo, sơ xuất, sơ xảy.", "giấu diếm, gian san, xuất xứ.", "giành giật, giả lả, suôn sẻ.", "suôn sẽ, suồng sả, giã lã."], "correctIndex": 2, "explain": "<b>Câu 16: Chọn C</b> <b>Giải thích:</b> &quot;Giành giật&quot;, &quot;giả lả&quot;, &quot;suôn sẻ&quot; là các từ viết <b>đúng chính tả</b>. Các phương án khác sai ở các từ: sơ xuất (đúng là sơ suất), giấu diếm (đúng là giấu giếm), suôn sẽ (đúng là suôn sẻ)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Nào có nghĩa gì cái chữ nho,</i><br><i>Ông nghè ông cống cũng nằm co.</i><br><i>Chi bằng đi học làm thầy phán,</i><br><i>Tối rượu sâm banh, sáng sữa bò.”</i><br>(Chữ Nho, Tú Xương)<br>Đâu là phương án phương án phản ánh đúng nhất cảm xúc của chủ thể trữ tình trong bài thơ trên?", "choices": ["Chua chát, mỉa mai và xót xa trước cảnh nền học vấn khoa cử từng được coi trọng nay trở nên lỗi thời, mất chỗ đứng.", "Cay đắng, mỉa mai và ngao ngán trước hiện tượng nhiều người dễ dàng từ bỏ giá trị cũ để chạy theo danh lợi thực dụng.", "Cay đắng, chua chát và đả kích sự đảo lộn các thang giá trị xã hội, khi nền khoa cử cũ bị lấn át bởi lối sống sính Tây.", "Mỉa mai, cay đắng và bất bình trước một thời thế khiến những người có học không còn được trọng dụng như trước."], "correctIndex": 2, "explain": "<b>Câu 17: Chọn C</b> <b>Giải thích:</b> Bài thơ thể hiện sự <b>cay đắng, chua chát</b> khi chứng kiến sự đảo lộn giá trị: chữ Nho cao quý bị coi thường, lối sống thực dụng kiểu Tây (rượu sâm banh, sữa bò) lên ngôi."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Câu nào sau đây phù hợp với chuẩn mực ngôn ngữ viết?", "choices": ["Bài thơ này hơi bị lạ so với cách dùng từ thông thường.", "Mong Thầy Cô xem xét về những thắc mắc của chúng em ạ.", "Thành công là kết quả của sự kiên trì, bởi vậy người làm biếng thì không thể thành công", "Như vậy, những tranh luận xoay quanh bộ phim đã dần đi đến hồi kết."], "correctIndex": 3, "explain": "<b>Câu 18: Chọn D</b> <b>Giải thích:</b> Câu D sử dụng ngôn ngữ <b>trang trọng, khách quan</b>, phù hợp với văn viết. Các câu khác mắc lỗi dùng từ khẩu ngữ (&quot;hơi bị lạ&quot;, &quot;ạ&quot;) hoặc diễn đạt thiếu chuyên nghiệp."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu có từ láy", "choices": ["Con mèo nằm còng queo trong chiếc giỏ nhỏ, mơ về miếng thịt cá hảo hạng.", "Cậu bé cần mẫn ngồi học, đôi mắt chuyên chú dõi theo từng dòng chữ trong sách.", "Người tham lam thường chỉ nghĩ đến lợi ích của mình.", "Mặt hồ phẳng lặng soi bóng những mái chùa cổ kính ven bờ sông."], "correctIndex": 0, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án B, còn đáp án tô trong đề là A — web đang dùng A.)</i><br><b>Câu 19: Chọn B</b> <b>Giải thích:</b> Từ <b>&quot;cần mẫn&quot;</b> là từ láy (láy vần), phù hợp với yêu cầu của đề bài."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Yếu tố “minh” trong phương án nào không mang nét nghĩa tương đồng với các phương án khác?", "choices": ["Những cậu học trò thông minh đã giải bài toán khó trong vòng năm phút.", "Làm việc quang minh chính đại thì không có gì phải sợ.", "Bước qua cánh rừng già, tôi có cảm giác như đang lạc vào một cõi u minh.", "Trong mọi hoạt động quản lý, sự minh bạch về thông tin và trách nhiệm giải trình là yếu tố quan trọng để xây dựng niềm tin nơi người dân."], "correctIndex": 2, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án A, còn đáp án tô trong đề là C — web đang dùng C.)</i><br><b>Câu 20: Chọn A</b> <b>Giải thích:</b> Trong các từ &quot;quang minh&quot;, &quot;u minh&quot;, &quot;minh bạch&quot;, yếu tố &quot;minh&quot; đều liên quan đến nghĩa là <b>sáng/rõ ràng</b>. Trong khi đó, &quot;thông minh&quot; (câu A) chỉ năng lực trí tuệ, nét nghĩa không tương đồng hoàn toàn với các từ còn lại trong ngữ cảnh này."}], "khongXaoTron": true}, {"noiDungChung": "<i>Nhiều quốc gia đã đi trước với các cách tiếp cận khác nhau khi đo hạnh phúc. Bhutan xây dựng chỉ số Gross National Happiness (GNH) với nhiều tầng dữ liệu định lượng và định tính, thậm chí hiến định trong hiến pháp, như một chuẩn mực phát triển đặt hạnh phúc lên hàng đầu.</i><br><i>Trong các thước đo quốc tế, World Happiness Report (WHR) là chỉ số phổ biến nhất. WHR chủ yếu khảo sát cảm nhận chủ quan để nắm bắt tâm trạng xã hội, được sử dụng rộng rãi nhờ dữ liệu toàn cầu đồng bộ và vị thế gắn với Liên Hợp Quốc.</i><br><i>Happy Planet Index (HPI) đi theo hướng phản biện hơn, với công thức lấy hạnh phúc cảm nhận nhân tuổi thọ, rồi chia cho mức phát thải trên đầu người (gần đây có cả phiên bản nhân thêm hiệu chỉnh bất bình đẳng giàu - nghèo).</i><br><i>Cách tiếp cận này nhấn mạnh &quot;hiệu quả hạnh phúc trên mỗi đơn vị tài nguyên&quot;, nhưng cách đo mức độ phát thải còn nhiều tranh luận, khiến HPI khó áp dụng chính thức và kém phổ biến trong chính sách.</i><br><i>Khác với hai chỉ số trên, OECD Well-being Framework không gộp hạnh phúc thành một con số duy nhất, mà để kết quả là một khung đa trụ cột song song như một dashboard chính sách. Mỗi lĩnh vực đời sống - từ thu nhập, việc làm, sức khỏe đến môi trường và giáo dục - có chỉ báo riêng, phù hợp cho nội bộ chính phủ trong thiết kế và đánh giá chính sách hơn là xếp hạng đối sánh.</i><br><i>Mỗi cách đo đều có lý lẽ riêng và những giới hạn nhất định. Một đánh giá hạnh phúc đáng tin cậy cần kết hợp dữ liệu định lượng và định tính. Nếu chỉ dựa vào các chỉ số khách quan như thu nhập, tuổi thọ hay phúc lợi, sẽ thiếu lớp cảm nhận vô hình nhưng quan trọng về đời sống tinh thần, cộng đồng và văn hóa - xã hội. Ngược lại, nếu chỉ dựa vào cảm nhận chủ quan, sai lệch là điều khó tránh.</i><br><i>Sống nhiều năm ở Nhật Bản và Singapore - hai quốc gia có GDP bình quân đầu người rất cao - tôi từng chứng kiến truyền thông xôn xao khi người dân bị đánh giá &quot;ngày càng kém hạnh phúc&quot;. Đơn cử như số liệu WHR 2023-2025 cho thấy Nhật Bản tụt hạng từ 47 xuống 55, Singapore giảm từ 25 xuống 34, mất vị trí dẫn đầu châu Á vào tay Đài Loan. Trong khi đó, Việt Nam, với thu nhập bình quân thấp hơn nhiều lần, lại thăng hạng từ 65 lên 54 rồi 46, nhờ văn hóa cộng đồng, sự gắn kết xã hội và sức bền tinh thần.</i><br><i>Không mô hình nào hoàn hảo. Nhưng các quốc gia đi trước đã vượt qua một ngưỡng then chốt: dám chọn cách đo, dám chuẩn hóa và dám để chính sách được soi chiếu bởi những con số gắn trực tiếp với đời sống con người.”</i><br>(Đo hạnh phúc của dân, Tô Kiên)", "cauHoi": [{"question": "Nội dung chính của đoạn văn trên là gì?", "choices": ["Giới thiệu thứ hạng hạnh phúc của một số quốc gia châu Á giai đoạn 2023-2025.", "Trình bày cách tiếp cận khác nhau trong việc đo hạnh phúc quốc gia và bình luận.", "Chứng minh rằng các chỉ số quốc tế hiện nay đều chưa đủ tin cậy để đánh giá hạnh phúc.", "Khẳng định không có cách đo chung cho hạnh phúc và không có quốc gia nào là hoàn hảo."], "correctIndex": 2, "explain": "<b>Câu 21: Chọn C</b> <b>Giải thích:</b> Văn bản liệt kê và phân tích các chỉ số GNH, WHR, HPI, OECD để cho thấy mỗi cách đo đều có ưu và nhược điểm riêng, từ đó khẳng định chưa có một hệ thống nào là hoàn hảo tuyệt đối"}, {"question": "Theo đoạn văn, điểm khác biệt nổi bật của OECD Well-being Framework so với các chỉ số còn lại là gì?", "choices": ["Đặt hạnh phúc vào vị trí trung tâm của hiến pháp quốc gia.", "Chủ yếu đo cảm nhận chủ quan để xếp hạng các quốc gia.", "Không gộp hạnh phúc thành một con số duy nhất mà xây dựng một khung đa trụ cột song song.", "Lấy hạnh phúc cảm nhận nhân với tuổi thọ rồi chia cho mức phát thải trên đầu người."], "correctIndex": 2, "explain": "<b>Câu 22: Chọn C</b> <b>Giải thích:</b> Văn bản nêu rõ: &quot;OECD Well-being Framework không gộp hạnh phúc thành một con số duy nhất, mà để kết quả là một <b>khung đa trụ cột song song</b>&quot;."}, {"question": "Văn bản trên chủ yếu trình bày thông tin theo cách nào?", "choices": ["Theo trật tự thời gian, từ quá khứ đến hiện tại của các mô hình đo hạnh phúc.", "Theo quan hệ nguyên nhân - kết quả, nhằm chỉ ra vì sao các quốc gia có mức độ hạnh phúc khác nhau.", "Theo cấu trúc so sánh - đối chiếu các cách tiếp cận đo hạnh phúc, đồng thời đánh giá ưu điểm và giới hạn của từng cách.", "Theo cấu trúc vấn đề - giải pháp, tập trung đề xuất một mô hình đo hạnh phúc tối ưu cho mọi quốc gia."], "correctIndex": 2, "explain": "<b>Câu 23: Chọn C</b> <b>Giải thích:</b> Tác giả lần lượt đưa ra các mô hình rồi chỉ ra điểm mạnh, điểm yếu của từng loại để so sánh (ví dụ: WHR mạnh về dữ liệu toàn cầu, HPI mạnh về hiệu quả tài nguyên nhưng khó áp dụng)."}, {"question": "Nhận định nào sau đây không phù hợp với nội dung đoạn văn?", "choices": ["HPI nhấn mạnh hiệu quả hạnh phúc trên mỗi đơn vị tài nguyên nhưng vẫn còn gây tranh luận về cách đo phát thải.", "WHR được sử dụng rộng rãi nhờ có dữ liệu toàn cầu đồng bộ và gắn với vị thế của Liên Hợp Quốc.", "OECD Well-being Framework phù hợp hơn với việc thiết kế, đánh giá chính sách nội bộ hơn là phục vụ xếp hạng đối sánh.", "Bhutan lựa chọn cách đo hạnh phúc hoàn toàn dựa trên cảm nhận chủ quan của người dân."], "correctIndex": 3, "explain": "<b>Câu 24: Chọn D</b> <b>Giải thích:</b> Thông tin trong bài cho biết Bhutan xây dựng chỉ số GNH với &quot;nhiều tầng dữ liệu <b>định lượng và định tính</b>&quot;, không phải &quot;hoàn toàn dựa trên cảm nhận chủ quan&quot;."}, {"question": "Từ đoạn văn, có thể rút ra kết luận nào sau đây?", "choices": ["Một hệ thống đánh giá hạnh phúc đáng tin cậy cần kết hợp giữa dữ liệu khách quan và cảm nhận chủ quan.", "Chỉ số hạnh phúc chỉ có ý nghĩa khi gắn với mức tăng trưởng GDP bình quân đầu người.", "Các quốc gia có thu nhập cao luôn đạt thứ hạng hạnh phúc cao hơn các quốc gia đang phát triển.", "Cần chuẩn hóa được một chỉ số duy nhất để phản ánh đầy đủ đời sống con người."], "correctIndex": 0, "explain": "<b>Câu 25: Chọn A</b> <b>Giải thích:</b> Tác giả kết luận: &quot;Một đánh giá hạnh phúc đáng tin cậy cần <b>kết hợp dữ liệu định lượng và định tính</b>&quot; (khách quan và chủ quan)."}], "khongXaoTron": true}, {"noiDungChung": "<i>Kant quan niệm ý thức đạo đức là quy luật của bổn phận. Có bổn phận được thôi thúc do sức mạnh và áp lực của dư luận từ bên ngoài; có bổn phận được thôi thúc do ý thức của chính lương tâm từ bên trong. Từ đó, Kant phân biệt hai loại hành động là hành động thích nghi theo bổn phận và hành động vì bổn phận. Ông kêu gọi: “Hãy hành động sao cho nhân tính trong bản thân mình cũng như nơi người khác luôn luôn được xem là cứu cánh và không bao giờ bị sử dụng như là phương tiện”.</i><br><i>Văn học gắn liền với ý thức đạo đức theo nghĩa thứ hai. Đó là tiếng nói của bổn phận và lương tâm ngay cả khi không có áp lực của xã hội và dư luận. Văn học khơi dậy sự ăn năn, cắn rứt của lương tâm con người về những tội lỗi mà có thể không một tòa án nào xử phạt được. Đó là sự sám hối, xưng tội của con người với chính bản thân mình: con người tự kết án, tự biện hộ, tự phán quyết và tự hòa giải với lương tâm mình. Có thể nói, ở nơi mà luật pháp, dư luận xã hội không can thiệp được, thì văn học có khả năng khơi dậy và tỉnh thức lương tri của con người.</i><br><i>Đạo đức là một thực thể luôn vận động và thay đổi theo sự tiến hoá của xã hội chứ không mang một khuôn khổ bất di bất dịch. Nói đúng hơn, trong đạo đức có phần căn cốt, bất biến; lại có phần biến đổi, thích nghi theo từng thời đại. Chẳng hạn, ở thời đại nào con người chân chính cũng coi trọng nghĩa vụ và danh dự; nhưng quan niệm về nghĩa vụ và danh dự thời nay không thể giống với quan niệm thời Racine, Corneille.. Cũng vậy, ở thời đại nào tình mẫu tử cũng thiêng liêng, sâu nặng; nhưng mỗi thời lại có cách đối xử với người phụ nữ khác nhau, và do vậy nhìn nhận vấn đề nữ quyền một cách khác nhau. Văn học tiên phong đấu tranh cho nữ quyền chính là góp phần làm chuyển biến đạo đức theo hướng tiến bộ.</i><br>(Văn học và văn hoá truyền thống, Huỳnh Như Phương)", "cauHoi": [{"question": "Quan điểm chính của văn bản là gì?", "choices": ["Đạo đức là hệ giá trị bất biến nên văn học chỉ có vai trò phản ánh.", "Văn học gắn bó với lương tâm con người và có khả năng thúc đẩy sự phát triển đạo đức xã hội.", "Triết học Kant là nền tảng duy nhất của mọi lý thuyết văn học hiện đại.", "Văn học chỉ có giá trị khi phê phán các tệ nạn xã hội."], "correctIndex": 1, "explain": "<b>Câu 26: Chọn B</b> <b>Giải thích:</b> Văn bản nhấn mạnh văn học khơi dậy lương tâm, giúp con người tự phán xét và góp phần làm chuyển biến đạo đức theo hướng tiến bộ"}, {"question": "Theo văn bản, văn học gắn với ý thức đạo đức theo nghĩa nào?", "choices": ["Sự tuân thủ các quy định pháp luật và sức ép dư luận.", "Sự đề cao lợi ích cá nhân trong mọi hoàn cảnh.", "Tiếng nói của bổn phận và lương tâm ngay cả khi không có áp lực bên ngoài.", "Sự phục tùng tuyệt đối những chuẩn mực truyền thống."], "correctIndex": 2, "explain": "<b>Câu 27: Chọn C</b> <b>Giải thích:</b> Văn bản khẳng định: &quot;Văn học gắn liền với ý thức đạo đức theo nghĩa thứ hai. Đó là <b>tiếng nói của bổn phận và lương tâm</b> ngay cả khi không có áp lực của xã hội&quot;."}, {"question": "Nhận định nào sau đây không phù hợp với nội dung văn bản?", "choices": ["Văn học có thể khơi dậy sự ăn năn, cắn rứt của lương tâm con người.", "Đạo đức vừa có phần bất biến, vừa có phần biến đổi theo thời đại.", "Mọi quan niệm về nghĩa vụ và danh dự ở các thời đại đều hoàn toàn giống nhau.", "Văn học đấu tranh cho nữ quyền góp phần làm chuyển biến đạo đức theo hướng tiến bộ."], "correctIndex": 2, "explain": "<b>Câu 28: Chọn C</b> Giải thích: Tác giả khẳng định quan niệm về nghĩa vụ và danh dự thay đổi theo thời đại (không giống với thời Racine, Corneille), do đó nhận định chúng &quot;hoàn toàn giống nhau&quot; là sai."}, {"question": "Bằng chứng nào được tác giả sử dụng để chứng minh đạo đức có tính vận động?", "choices": ["Con người luôn có lương tâm và biết tự phán xét mình.", "Quan niệm về nghĩa vụ, danh dự và vấn đề nữ quyền thay đổi theo từng thời đại.", "Luật pháp không thể xử phạt mọi lỗi lầm của con người.", "Văn học có thể thay thế vai trò của pháp luật."], "correctIndex": 1, "explain": "<b>Câu 29: Chọn B</b> <b>Giải thích:</b> Tác giả lấy ví dụ về việc quan niệm nghĩa vụ, danh dự và nữ quyền thay đổi qua các thời kỳ để minh chứng cho tính vận động của đạo đức"}, {"question": "Đâu là phương án phê phán phù hợp nhất cho quan điểm trên?", "choices": ["Văn học có thể khơi dậy sự tự vấn và thức tỉnh lương tâm, nhưng hiệu quả cảm hóa ấy không phải lúc nào cũng đủ để thay thế vai trò của pháp luật hay những cơ chế điều chỉnh xã hội khác.", "Văn học có khả năng tác động đến đời sống nội tâm con người, tuy nhiên sự chuyển biến đạo đức còn phụ thuộc chủ yếu vào trải nghiệm sống và ý thức tự rèn luyện của mỗi cá nhân.", "Sự ăn năn và cắn rứt lương tâm mà văn học khơi dậy đôi khi chỉ dừng ở cảm xúc nhất thời, nếu không gắn với hành động sửa đổi cụ thể thì khó tạo nên thay đổi bền vững.", "Văn học giúp con người nhận diện sai lầm của bản thân, song không phải mọi độc giả đều tiếp nhận tác phẩm theo cùng một chiều hướng đạo đức như tác giả mong muốn."], "correctIndex": 2, "explain": "<b>Câu 30: Chọn C</b> <b>Giải thích:</b> Đáp án này đưa ra một góc nhìn phản biện hợp lý: cảm xúc từ văn học (sự ăn năn) có thể chỉ là nhất thời nếu không biến thành hành động thực tế, giúp làm sâu sắc thêm vấn đề được thảo luận<br><table class=\"bang-de\"><tr><td><b>Câu</b></td><td><b>1</b></td><td><b>2</b></td><td><b>3</b></td><td><b>4</b></td><td><b>5</b></td><td><b>6</b></td><td><b>7</b></td><td><b>8</b></td><td><b>9</b></td><td><b>10</b></td><td><b>11</b></td><td><b>12</b></td><td><b>13</b></td><td><b>14</b></td><td><b>15</b></td></tr><tr><td>ĐA</td><td>A</td><td>C</td><td>A</td><td>B</td><td>B</td><td>B</td><td>A</td><td>D</td><td>A</td><td>A</td><td>D</td><td>B</td><td>B</td><td>D</td><td>D</td></tr><tr><td><b>Câu</b></td><td><b>16</b></td><td><b>17</b></td><td><b>18</b></td><td><b>19</b></td><td><b>20</b></td><td><b>21</b></td><td><b>22</b></td><td><b>23</b></td><td><b>24</b></td><td><b>25</b></td><td><b>26</b></td><td><b>27</b></td><td><b>28</b></td><td><b>29</b></td><td><b>30</b></td></tr><tr><td>ĐA</td><td>C</td><td>C</td><td>D</td><td>A</td><td>C</td><td>B</td><td>C</td><td>C</td><td>D</td><td>A</td><td>B</td><td>C</td><td>C</td><td>B</td><td>C</td></tr></table>"}], "khongXaoTron": true}], "anh": [{"noiDungChung": "<b><i>Câu 31-35: Mark the letter A, B, C, or D on your answer sheet to indicate the correct answer to each of the following questions.</i></b>", "cauHoi": [{"question": "Before launching the software, you need to go _____ all the settings to ensure they<br>are correct.", "choices": ["over", "into", "on", "with"], "correctIndex": 0, "explain": "<b>Câu 31. Chọn A</b><br><b>Giải thích:</b> Cấu trúc <b>Go over</b> (phrasal verb) có nghĩa là kiểm tra, xem xét kỹ lưỡng.<br><b>Dịch:</b> Trước khi khởi chạy phần mềm, bạn cần kiểm tra lại tất cả các cài đặt để đảm bảo chúng chính xác."}, {"question": "I was hoping to test the program, but the system _____ before I had the chance.", "choices": ["shut down", "was shutting", "had shut down", "would shut"], "correctIndex": 2, "explain": "<b>Câu 32. Chọn C</b><br><b>Giải thích:</b> Sự việc &quot;hệ thống bị tắt&quot; xảy ra trước hành động &quot;có cơ hội test&quot; (quá khứ đơn), nên ta dùng thì <b>Quá khứ hoàn thành</b> ($Had + V3/ed$) để diễn tả hành động xảy ra trước một hành động khác trong quá khứ."}, {"question": "This app provides data visualization tools that are _____ its analytical features.", "choices": ["as useful as", "more usefully than", "as usefully as", "so usefully as"], "correctIndex": 0, "explain": "<b>Câu 33. Chọn A</b><br><b>Giải thích:</b> Cấu trúc so sánh bằng: <b>as + adj + as</b>. Ở đây &quot;tools&quot; là danh từ, &quot;are&quot; là động từ to-be nên cần tính từ &quot;useful&quot;.<br><b>Dịch:</b> Ứng dụng này cung cấp các công cụ trực quan hóa dữ liệu hữu ích như các tính năng phân tích của nó."}, {"question": "Maria wants to become a software engineer, so she needs to learn skills in _____.", "choices": ["computer programming", "computer programmer", "computerized programming", "computerized programmer"], "correctIndex": 0, "explain": "<b>Câu 34. Chọn A</b><br><b>Giải thích:</b> <b>Computer programming</b> (lập trình máy tính) là một danh từ chỉ lĩnh vực/kỹ năng. &quot;Programmer&quot; là người lập trình (không phù hợp ngữ cảnh &quot;learn skills in&quot;)."}, {"question": "A podcast is an online show where hosts often discuss _____ of topics with their<br>audience.", "choices": ["too much", "wide amounts", "too many", "a wide range"], "correctIndex": 3, "explain": "<b>Câu 35. Chọn D</b><br><b>Giải thích: Cụm từ cố định a wide range of + N (số nhiều): một phạm vi rộng/nhiều loại cái gì đó.</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 36-40: Mark the letter A, B, C, or D on your answer sheet to indicate the wrong word use/form to each of the following statement.</i></b>", "cauHoi": [{"question": "I installed <u>a</u> latest update to <u>the</u> application, but it kept <u>crashing</u> during the first few <u>runs</u>.", "choices": ["a", "the", "crashing", "run"], "correctIndex": 0, "explain": "<b>Câu 36. Chọn A</b><br><b>Lỗi sai:</b> &quot;a&quot; -&gt; Sửa thành <b>&quot;the&quot;</b>.<br><b>Giải thích:</b> Trước tính từ so sánh nhất &quot;latest&quot; (mới nhất), ta phải dùng mạo từ xác định &quot;the&quot;."}, {"question": "<u>A</u> virtual assistant, one of <u>the most useful</u> tools in modern technology, <u>are</u> becoming increasingly popular in <u>households</u>.", "choices": ["a", "the most useful", "are", "households"], "correctIndex": 2, "explain": "<b>Câu 37. Chọn C</b><br><b>Lỗi sai:</b> &quot;are&quot; <span class=\"ct\">→</span> Sửa thành <b>&quot;is&quot;</b>.<br><b>Giải thích:</b> Chủ ngữ chính là &quot;A virtual assistant&quot; (số ít), cụm &quot;one of the...&quot; chỉ là phần giải thích thêm nên động từ phải chia số ít."}, {"question": "<u>An</u> interesting fact is <u>that</u> the <u>cat&#x27;s</u> whiskers are shorter than the <u>dog</u>.", "choices": ["an", "that", "cat’s", "dog"], "correctIndex": 3, "explain": "<b>Câu 38. Chọn D</b><br><b>Lỗi sai:</b> &quot;dog&quot; -&gt; Sửa thành <b>&quot;dog&#x27;s&quot;</b> hoặc <b>&quot;those of the dog&quot;</b>.<br><b>Giải thích:</b> Lỗi so sánh không tương xứng. Ta phải so sánh &quot;whiskers&quot; (ria) của mèo với &quot;whiskers&quot; của chó, chứ không thể so sánh ria mèo với con chó"}, {"question": "Chris’s backpack <u>was</u> left in <u>the</u> classroom, and the teacher returned <u>it</u> to <u>her</u>.", "choices": ["was", "the", "it", "her"], "correctIndex": 3, "explain": "<b>Câu 39. Chọn D</b><br><b>Lỗi sai: &quot;her&quot; -&gt; Sửa thành &quot;him&quot;.</b><br><b>Giải thích: Chủ ngữ là &quot;Chris&quot; (thường là nam trong ngữ cảnh này, hoặc xét tính nhất quán của đại từ), nhưng quan trọng nhất là lỗi quy chiếu đại từ.</b>"}, {"question": "The teacher <u>gave</u> the assignment <u>to</u> the students <u>which</u> needed extra <u>help</u>.", "choices": ["gave", "to", "which", "help"], "correctIndex": 2, "explain": "<b>Câu 40. Chọn C</b><br><b>Lỗi sai:</b> &quot;which&quot; -&gt; Sửa thành <b>&quot;who&quot;</b>.<br><b>Giải thích:</b> Đại từ quan hệ thay thế cho danh từ chỉ người &quot;the students&quot; phải là &quot;who&quot;, không dùng &quot;which&quot; (dành cho vật)."}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 41-45: Which of the following best restates each of the given sentences?</i></b>", "cauHoi": [{"question": "Emily said, &quot;I think you should back up your files before installing the update.&quot;", "choices": ["Emily suggested that I back up my files before installing the update.", "Emily told me to back up my files because the update would delete them.", "Emily thought that the update was safe to install without backups.", "Emily advised that I avoid installing the update until I had backups."], "correctIndex": 0, "explain": "<b>Câu 41. Chọn A</b><br><b>Giải thích:</b> Cấu trúc khuyên bảo &quot;I think you should...&quot; tương đương với cấu trúc đề xuất: <b>S + suggested + (that) + S + (should) + V (bare)</b>."}, {"question": "There was a power outage due to an overloaded electrical circuit.", "choices": ["The power would not have gone out if the circuit had not been overloaded.", "If the electrical circuit were repaired, the power would not have gone out.", "Unless the circuit was overloaded, the power outage could not occur.", "The overloaded circuit caused the power outage immediately."], "correctIndex": 0, "explain": "<b>Câu 42. Chọn A</b><br><b>Giải thích:</b> Câu gốc nói về nguyên nhân kết quả trong quá khứ. Dùng <b>Câu điều kiện loại 3</b> (If + had + V3/ed, S + would + have + V3/ed) để diễn tả giả thiết trái ngược với quá khứ."}, {"question": "This cup of coffee is strong while the other two are too weak.", "choices": ["Of the three cups of coffee, this one is the strongest.", "The other two cups of coffee are stronger than this one.", "No other coffee is stronger than this cup of coffee.", "One of the three cups of coffee is too bitter to drink."], "correctIndex": 0, "explain": "<b>Câu 43. Chọn A</b><br><b>Giải thích:</b> &quot;Một cái mạnh, hai cái kia yếu&quot; đồng nghĩa với việc cái này là <b>mạnh nhất</b> trong số ba cái (so sánh nhất)."}, {"question": "Warning! Turn off the gas to prevent an explosion.", "choices": ["Turn off the gas quickly so you can cause an explosion.", "If you turn off the gas, the explosion will still occur.", "The gas must be turned off to prevent an explosion.", "The explosion will occur quickly if the gas is turned off."], "correctIndex": 2, "explain": "<b>Câu 44. Chọn C</b><br><b>Giải thích:</b> Câu bị động: &quot;Việc tắt gas là cần thiết để ngăn chặn vụ nổ&quot;. Các phương án khác sai lệch về nghĩa (gây ra nổ hoặc nổ vẫn xảy ra)."}, {"question": "Jane must feel relieved if I help her with her project.", "choices": ["I think that Jane will probably feel relieved if I offer to help her with her project.", "I must help Jane with her project so that she will feel relieved.", "I’m certain that Jane will feel relieved if I offer my assistance with her project.", "It is possible that Jane will feel relieved if I offer my assistance with her project."], "correctIndex": 2, "explain": "<b>Câu 45. Chọn C</b><br><b>Giải thích:</b> Cấu trúc <b>Must + V</b> ở đây chỉ sự phỏng đoán chắc chắn gần như 100% ở hiện tại. &quot;I&#x27;m certain&quot; (Tôi chắc chắn) phản ánh đúng sắc thái này."}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 46-52: Read the passage carefully and choose an option (A, B, C, or D) that best answers each question. Choose an option (A, B, C, or D) that best answers each question.</i></b><br>Multiculturalism is increasingly becoming an integral aspect of modern societies around the world. It promotes the idea of bringing together people from diverse cultural backgrounds to live harmoniously in the same community. By embracing multiculturalism, societies gain access to a rich tapestry of traditions, cuisines, and artistic expressions, ultimately enhancing the quality of life for everyone involved.<br><b>2. </b>Multicultural communities often showcase a beautiful blend of customs, celebrations, and traditions. Festivals such as Lunar New Year, Diwali, Eid, and Hanukkah are now celebrated alongside Christmas, Thanksgiving, and other national holidays in many countries. These shared<br>experiences help preserve the cultural heritage of various communities while also encouraging understanding, respect, and appreciation among people from different ethnic backgrounds. <b>They</b> create opportunities for cross-cultural interaction, allowing individuals to learn about and enjoy traditions they might not otherwise experience.<br><b>3.</b> The impact of multiculturalism extends beyond cultural enrichment—it also plays a crucial<br>role in economic development. Immigrants frequently bring unique skills, talents, and perspectives<br>that contribute significantly to innovation and growth. They often fill essential roles in industries that face labor shortages, adding value through their hard work and expertise. Additionally, multiculturalism promotes the growth of diverse businesses. Restaurants offering global cuisine, international music festivals, and businesses specializing in multicultural products <b>thrive</b> in environments that celebrate diversity. These businesses not only create jobs but also stimulate local economies by attracting both residents and tourists who are eager to experience a variety of cultural<br>offerings.<br><b>4.</b> However, achieving true multicultural harmony is not without its challenges. Misunderstandings, stereotypes, and prejudice still exist, creating barriers to acceptance and inclusion. Education is crucial in addressing these challenges. Schools and workplaces that actively teach about cultural diversity, tolerance, and inclusion can play an essential role in breaking down<br>these barriers and fostering greater understanding among individuals from different backgrounds.<br><b>5.</b> Despite its challenges, multiculturalism remains a vital force for social and economic progress. It allows societies to experience the richness of human diversity while working toward mutual respect, unity, and shared prosperity. By embracing multiculturalism, we build a foundation for a<br>more harmonious and dynamic world.", "cauHoi": [{"question": "What is the main idea of the passage?", "choices": ["The challenges of achieving multicultural harmony.", "The economic benefits of multiculturalism.", "The importance of multiculturalism in modern societies.", "How multiculturalism promotes global tourism."], "correctIndex": 2, "explain": "<b>Câu 46. Chọn C:</b> Tầm quan trọng của đa văn hóa trong xã hội hiện đại (bao quát cả văn hóa, kinh tế, giáo dục)."}, {"question": "According to paragraph 1, what does multiculturalism promote?", "choices": ["The elimination of all cultural traditions.", "Living harmoniously in diverse communities.", "The replacement of local customs with global ones.", "The rejection of national holidays."], "correctIndex": 1, "explain": "<b>Câu 47. Chọn B:</b> Sống hòa hợp trong các cộng đồng đa dạng (Dòng 2 đoạn 1)."}, {"question": "According to paragraph 2, what does the word &quot;<b>they</b>&quot; refer to?", "choices": ["National holidays", "Festivals like Lunar New Year, Diwali, and Eid", "Opportunities for cross-cultural interaction", "Traditions of various communities"], "correctIndex": 1, "explain": "<b>Câu 48. Chọn B: Các lễ hội (Lunar New Year, Diwali...). &quot;They&quot; ở đầu câu sau thay thế cho các danh từ festival được liệt kê trước đó.</b>"}, {"question": "In paragraph 2, which of the following is NOT a benefit of celebrating multiple festivals?", "choices": ["Preserving cultural heritage.", "Encouraging mutual respect and understanding.", "Creating opportunities for cultural interaction.", "Reducing labor shortages in industries."], "correctIndex": 3, "explain": "<b>Câu 49. Chọn D: Giảm thiếu hụt lao động là lợi ích về kinh tế (đoạn 3), không phải lợi ích của việc tổ chức lễ hội (đoạn 2).</b>"}, {"question": "In paragraph 3, what is the word &quot;<b>thrive</b>&quot; closest in meaning to?", "choices": ["succeed", "decline", "struggle", "survive."], "correctIndex": 0, "explain": "<b>Câu 50. Chọn A: Thrive = Succeed/Prosper (Phát triển mạnh, thành công).</b>"}, {"question": "In paragraph 4, why is education crucial to overcoming challenges in<br>multiculturalism?", "choices": ["It helps individuals assimilate into a dominant culture.", "It teaches cultural diversity, tolerance, and inclusion to break down barriers.", "It eliminates the need for celebrating multiple festivals.", "It focuses on promoting economic benefits over cultural harmony."], "correctIndex": 1, "explain": "<b>Câu 51. Chọn B: Nó dạy về sự đa dạng, khoan dung để phá bỏ rào cản (Thông tin đoạn 4).</b>"}, {"question": "In paragraph 5, what can be inferred about multiculturalism today?", "choices": ["It is a simple process that requires little effort to implement.", "It faces challenges but remains essential for societal progress.", "It discourages cultural diversity in favor of economic growth.", "It has resolved all issues related to prejudice and stereotypes."], "correctIndex": 1, "explain": "<b>Câu 52. Chọn B: Đa văn hóa có thách thức nhưng vẫn thiết yếu cho sự tiến bộ (Tổng kết từ đoạn 4 và 5).</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 53-60</b>: <b>Read the passage carefully and Choose an option (A, B, C, or D) that best answers each question.</b><br><b>1</b>. Growing up in Vietnam, many stories about guerrilla warfare have been passed down through<br>generations. These stories are not just tales of battle but accounts of resilience and bravery. Guerrilla warfare played a significant role in the country&#x27;s struggle for independence, particularly during the Vietnam War. For many Vietnamese, it was the weapon of the weak, used to combat a much stronger and better-equipped opponent, relying on creativity, adaptability, and sheer<br>determination.<br><b>2.</b> Vietnam&#x27;s geography—its dense jungles, mountains, and river systems—was a perfect environment for guerrilla tactics. The Vietnamese guerrillas, known as the Viet Cong in the south, used their knowledge of the terrain to create an intricate system of tunnels, hideouts, and ambush points. These fighters, often villagers who took up arms, were able to evade and harass enemy forces through hit-and-run tactics, laying traps, and blending seamlessly back into the civilian population. <b>Their</b> ability to <b>vanish</b> into the landscape frustrated the conventional military forces that were unaccustomed to such tactics.<br><b>3.</b> The use of guerrilla warfare was not only a military strategy but also a cultural reflection of<br>the Vietnamese people’s deep connection to their land. The resilience demonstrated during these<br>conflicts is seen as an embodiment of national pride. Many elders recall the importance of unity and community support during these times. Villagers would assist guerrilla fighters by providing food, shelter, and information, often risking their lives. This sense of <b>solidarity</b> and determination helped create an environment where the guerrillas could thrive and continue their struggle for<br>independence.<br><b>4.</b> However, guerrilla warfare in Vietnam also had its darker sides. The distinction between combatants and civilians was often blurred, leading to significant suffering for many. Both sides of the conflict experienced loss and trauma, and the war left deep scars on the population. Despite this, the stories shared about these struggles emphasize the ingenuity and endurance of the Vietnamese people. Guerrilla warfare, for the Vietnamese, symbolizes a spirit of resistance, the ability to overcome overwhelming odds, and the ultimate quest for freedom and self-determination. These stories continue to shape the national identity and remind people of their shared history.", "cauHoi": [{"question": "The best title of the passage can be _______.", "choices": ["The Legacy of Guerrilla Warfare in Vietnam", "The Geography of Vietnam&#x27;s Guerrilla Strategies", "How Guerrilla Tactics Failed During the Vietnam War", "The Impact of Guerrilla Warfare on Modern Conflicts"], "correctIndex": 0, "explain": "<b>Câu 53. Chọn A:</b> Di sản của chiến tranh du kích tại Việt Nam (Bài viết nói về lịch sử, địa lý và tầm ảnh hưởng văn hóa)."}, {"question": "In paragraph 2, what does the word &quot;<b>their</b>&quot; refer to?", "choices": ["Enemy forces", "The Viet Cong guerrillas", "Dense jungles and rivers", "Military tactics."], "correctIndex": 1, "explain": "<b>Câu 54. Chọn B:</b> Các du kích Việt Cộng (The Vietnamese guerrillas)."}, {"question": "According to paragraph 2, how did Vietnamese geography contribute to guerrilla warfare?", "choices": ["It made it difficult for villagers to communicate.", "It provided a perfect environment for tunnels and ambushes.", "It created obstacles for guerrilla fighters to hide.", "It limited the movement of both guerrilla fighters and their opponents."], "correctIndex": 1, "explain": "<b>Câu 55. Chọn B:</b> Cung cấp môi trường hoàn hảo cho hầm ngầm và phục kích (Đoạn 2: &quot;perfect environment for... tunnels...&quot;)."}, {"question": "In paragraph 2, the word &quot;<b>vanish</b>&quot; most closely means:", "choices": ["disappear", "attack", "retreat", "relocate"], "correctIndex": 0, "explain": "<b>Câu 56. Chọn A:</b> Vanish = Disappear (Biến mất)."}, {"question": "In paragraph 3, it is <b>NOT</b> mentioned that villagers:", "choices": ["supplied guerrilla fighters with food and shelter.", "risked their lives to assist guerrilla fighters.", "fought directly alongside the guerrilla fighters in battle.", "provided critical information to guerrilla fighters."], "correctIndex": 2, "explain": "<b>Câu 57. Chọn C:</b> Không có thông tin nói dân làng &quot;trực tiếp cầm súng chiến đấu cùng&quot; (họ chỉ hỗ trợ thức ăn, nơi ở, thông tin)."}, {"question": "In paragraph 3, the author uses the word &quot;<b>solidarity</b>&quot; to:", "choices": ["Highlight the social challenges faced by guerrilla fighters.", "Emphasize the unity and mutual support of the Vietnamese people.", "Criticize the lack of external help during the war.", "Compare the guerrilla fighters’ tactics to modern warfare."], "correctIndex": 1, "explain": "<b>Câu 58. Chọn B:</b> Nhấn mạnh sự đoàn kết và hỗ trợ lẫn nhau của người dân Việt Nam."}, {"question": "What can be inferred about the Viet Cong&#x27;s use of guerrilla tactics?", "choices": ["They relied on foreign support for their success.", "Their knowledge of the terrain gave them a critical advantage.", "They primarily avoided civilian involvement in their efforts.", "They focused on large-scale attacks instead of small ambushes."], "correctIndex": 1, "explain": "<b>Câu 59. Chọn B:</b> Kiến thức về địa hình mang lại lợi thế quan trọng (Đoạn 2)."}, {"question": "From paragraphs 2, 3, and 4, it can be inferred that guerrilla warfare in Vietnam:", "choices": ["was purely a military strategy with no cultural significance.", "relied heavily on the involvement and support of local communities.", "was unsuccessful in creating national unity.", "led to Vietnam becoming isolated from international allies."], "correctIndex": 1, "explain": "<b>Câu 60. Chọn B:</b> Chiến tranh du kích dựa rất nhiều vào sự tham gia và hỗ trợ của cộng đồng địa phương."}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Nồi áp suất hoạt động dựa trên nguyên lý hệ kín: hơi nước tích tụ làm tăng áp suất lên khoảng 2 atm, đẩy nhiệt độ sôi của nước từ 100°C lên 121°C. Về mặt nhiệt động lực học, môi trường này thúc đẩy hai quá trình then chốt:<br>Thủy phân Peptide: Nhiệt độ cao cung cấp năng lượng để cắt đứt liên kết peptide, giải phóng các amino acid (như Lysine, Glycine) và các hợp chất chứa lưu huỳnh (Cysteine).<br>Phản ứng Maillard: Các amino acid phản ứng với đường khử tạo ra các hợp chất vòng (Furan, Pyrazine) mang hương thơm và polymer Melanoidin tạo màu nâu.<br>Mỗi phản ứng này đều có một mức năng lượng hoạt hóa (<span class=\"ct\">E<sub>a</sub></span>) nhất định – rào cản năng lượng mà các phân tử phải vượt qua để phản ứng xảy ra; giá trị này là hằng số đặc trưng cho bản chất của mỗi phản ứng và không phụ thuộc vào nhiệt độ. Theo quy tắc Van&#x27;t Hoff, khi nhiệt độ tăng thêm 10°C, tốc độ phản ứng (<span class=\"ct\">v</span>) tăng từ 2 đến 4 lần (hệ số nhiệt độ <span class=\"ct\">γ</span>).", "cauHoi": [{"question": "Có bao nhiêu nhận định sau đây đúng theo nội dung bài đọc?<br>(1) Melanoidin là sản phẩm tạo màu từ phản ứng giữa amino acid và đường khử.<br>(2) Nồi áp suất đóng vai trò là chất xúc tác làm giảm năng lượng hoạt hóa của phản ứng.<br>(3) Việc tăng nhiệt độ giúp tăng tỉ lệ va chạm hiệu quả giữa các phân tử chất phản ứng.<br>(4) Sự thay đổi màu sắc và mùi vị trong nồi là kết quả của các biến đổi hóa học.", "choices": ["1.", "2.", "3.", "4."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b><br><b>Câu 103 chọn C</b> (Ý 1, 3, 4 đúng; ý 2 sai vì nhiệt độ không phải chất xúc tác)."}, {"question": "Khi chuyển từ đun sôi thông thường (101°C) sang nồi áp suất (121°C), đại lượng nào sau đây của phản ứng Maillard sẽ <b>KHÔNG</b> thay đổi?", "choices": ["Động năng trung bình của các phân tử.", "Tốc độ tạo thành hợp chất Melanoidin.", "Năng lượng hoạt hóa (<span class=\"ct\">E<sub>a</sub></span>).", "Tần số va chạm giữa các phân tử."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b><br>Loại A, B, D: Khi nhiệt độ tăng, động năng tăng <span class=\"ct\">→</span> tần số va chạm tăng <span class=\"ct\">→</span> tốc độ phản ứng (<span class=\"ct\">v</span>) tăng theo quy tắc Van&#x27;t Hoff.<br><b>Chọn C:</b> Năng lượng hoạt hóa (<span class=\"ct\">E<sub>a</sub></span>) là &quot;rào cản năng lượng&quot; cố định của một phản ứng cụ thể. Nó chỉ thay đổi khi thay đổi bản chất phản ứng hoặc dùng chất xúc tác, không phụ thuộc vào nhiệt độ."}, {"question": "Một món hầm đạt độ chín yêu cầu sau 120 phút ở 101°C. Nếu nấu trong nồi áp suất ở 121°C với hệ số nhiệt độ <span class=\"ct\">γ = 2</span>, thời gian cần thiết để đạt độ chín tương đương là bao nhiêu?", "choices": ["60 phút.", "30 phút.", "15 phút.", "40 phút."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 105: Chọn B</b> (<span class=\"ct\">ΔT = 20°C →</span> Tốc độ tăng <span class=\"ct\">2<sup>2</sup> = 4</span> lần<br><span class=\"ct\">→</span> Thời gian giảm 4 lần: <span class=\"ct\">120/4 = 30</span> phút)."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br>Hạt nhân của các nguyên tử được cấu tạo từ các nucleon (proton và neutron). Mặc dù các proton nằm rất gần nhau trong không gian cực nhỏ của hạt nhân (khoảng <span class=\"ct\">10<sup>−15</sup></span> m) và chịu lực đẩy tĩnh điện Coulomb rất lớn, nhưng hạt nhân vẫn bền vững nhờ sự tồn tại của <b>lực hạt nhân</b>. Đây là lực tương tác mạnh, có bán kính tác dụng rất ngắn nhưng cường độ lớn hơn nhiều lần so với lực đẩy tĩnh điện.<br>Một số hạt nhân không bền vững sẽ tự phát phóng xạ để trở nên ổn định hơn. Trong phân rã <span class=\"ct\">β<sup>−</sup></span>, một neutron bên trong hạt nhân biến đổi thành một proton, một electron và một hạt phản neutrino (\\(^1_0n \\rightarrow ^1_1p + ^0_{-1}e + \\bar{\\nu}_e\\)).<br>\\(^1_0n \\rightarrow ^1_1p + ^0_{-1}e + \\bar{\\nu}_e\\)<br>Xét một quá trình phóng xạ <span class=\"ct\">β<sup>−</sup></span>đơn giản hóa (bỏ qua năng lượng của phản neutrino), trong đó một hạt nhân mẹ đứng yên phân rã thành một hạt nhân con và một electron.<br><span class=\"ct\"><sub>Z</sub><sup>A</sup>X → <sub>Z+1</sub><sup>A</sup>Y + β<sup>−</sup></span> (trong đó A là số nucleon của hạt nhân và Z là số proton).<br>Do khối lượng của hạt nhân con rất lớn so với khối lượng của electron (\\(m_{con} \\gg m_e\\)), nên động năng của hạt nhân con sinh ra không đáng kể.", "cauHoi": [{"question": "Trong quá trình phóng xạ <span class=\"ct\">β<sup>−</sup></span>, một neutron biến đổi thành một proton và phóng ra một electron cùng với một hạt khác. Đặc điểm của hạt đi kèm này là:", "choices": ["Mang điện tích dương, khối lượng lớn.", "Không mang điện, khối lượng rất bé (xấp xỉ bằng 0).", "Mang điện tích âm, khối lượng bằng electron.", "Là một hạt proton khác."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Phương trình:</b> \\(^1_0n \\rightarrow ^1_1p + ^0_{-1}e + \\bar{\\nu}_e\\)<br><b>Bảo toàn điện tích:</b> Vế trái <span class=\"ct\">Z = 0</span>, vế phải đã có <span class=\"ct\">p( + 1)</span> và <span class=\"ct\">e(−1)</span> tổng bằng <span class=\"ct\">0</span>. <span class=\"ct\">→</span> Hạt đi kèm <b>không mang điện</b>.<br><b>Bảo toàn số khối:</b> Vế trái <span class=\"ct\">A = 1</span>, vế phải đã có <span class=\"ct\">p(1)</span> và <span class=\"ct\">e(0)</span> tổng bằng <span class=\"ct\">1</span>. <span class=\"ct\">→</span> Hạt đi kèm có <b>khối lượng xấp xỉ bằng 0</b>.<br><b>Kết luận:</b> Hạt thỏa mãn cả hai điều kiện trên là hạt <b>phản neutrino</b>. <b>=&gt; Chọn B.</b>"}, {"question": "Cho các mệnh đề sau đây về cấu tạo và sự biến đổi hạt nhân:<br>(1) Trong phân rã <span class=\"ct\">β<sup>−</sup></span>, hạt electron được tạo ra bằng cách một hạt proton biến đổi thành một neutron và một phản neutrino.<br>(2) Lực hạt nhân có bản chất là lực hút tĩnh điện giữa các proton và neutron nên giúp hạt nhân bền vững.<br>(3) Các hạt nucleon trong hạt nhân bao gồm proton và neutron, chúng có khối lượng xấp xỉ bằng nhau nhưng neutron có điện tích lớn hơn proton.<br>(4) Trong phản ứng phân rã hạt nhân mẹ đứng yên, sản phẩm nào có khối lượng lớn hơn thì sẽ mang động năng nhỏ hơn.<br>Số mệnh đề <b>SAI</b> là:", "choices": ["1.", "2.", "3.", "4."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> (1) SAI: Neutron biến đổi thành Proton (trong phân rã <span class=\"ct\">β<sup>−</sup></span>).<br>(2) SAI: Lực hạt nhân không phải là lực tĩnh điện (nếu là lực tĩnh điện thì các proton sẽ đẩy nhau).<br>(3) SAI: Neutron không mang điện (điện tích bằng 0), nên không thể lớn hơn điện tích của proton (<span class=\"ct\">+ e</span>).<br>(4) ĐÚNG: Do khối lượng hạt nhân con rất lớn nên động năng của hạt nhân con rất bé<br><span class=\"ct\">⇒</span> Đáp án C (3 câu sai)."}, {"question": "Giả thiết trong một phóng xạ, động năng của electron được phóng ra là E, nhiệt lượng do phóng xạ này tỏa ra (gồm tổng các động năng của tia phóng xạ và của hạt nhân con) xấp xỉ bằng:", "choices": ["E.", "2E.", "0.", "<img class=\"anh-de\" src=\"data/anh/l13/cbc3a1e147cfde89.png\" alt=\"\" style=\"width:19px;height:41px;vertical-align:middle\">."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b> Xét phản ứng phóng xạ: <span class=\"ct\"><sub>Z</sub><sup>A</sup>X → <sub>Z+1</sub><sup>A</sup>Y + β<sup>−</sup></span><br>Năng lượng phóng xạ toả ra gồm tổng các động năng của tia phóng xạ và của hạt nhân con tức là: <span class=\"ct\">Q = K<sub>Y</sub> + K<sub>β</sub></span><br>Trong đó đề bài nói “Do khối lượng của hạt nhân Y con rất lớn so với khối lượng của electron (\\(m_{con} \\gg m_e\\)), nên động năng của hạt nhân con sinh ra không đáng kể” tức là <span class=\"ct\">K<sub>Y</sub> = 0</span> và <span class=\"ct\">K<sub>β</sub> = Q = E</span> <span class=\"ct\"><b> ⇒ </b></span><b> Chọn A</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br>Loài cá tuyết nam cực (họ Chaenichthyidae) có hoạt động và trao đổi chất rất chậm. Chúng là nhóm động vật có xương sống duy nhất không chứa hồng cầu và sắc tố hemoglobin. Cá tuyết có hình dạng trong suốt, nặng khoảng 2kg và dài khoảng 0,6m. Trong hệ gen của cá tuyết, gen β-globin và gen α-globin bị đột biến thành gen giả, không tham gia tổng hợp Hemoglobin. Cá tuyết thuộc nhóm động vật biến nhiệt. Máu cá tuyết thiếu hemoglobin giúp cá thích nghi tốt trong điều kiện sống vùng Nam cực nhiệt độ lạnh (-2<sup>0</sup>C) và nồng độ O<sub>2</sub> cao. Cá tuyết thu nhận O<sub>2</sub> chủ yếu bằng cơ chế khuếch tán trực tiếp vào máu. Cá tuyết có diện tích mang nhỏ nên hoạt động trao đổi khí chủ yếu qua da. Một lượng lớn mạch máu nhỏ dưới da giúp cá nhận đủ O<sub>2</sub> khuếch tán.", "cauHoi": [{"question": "Nhiệt độ trong nước thay đổi thì:", "choices": ["Nhiệt độ cơ thể cá thay đổi theo chiều thay đổi của nhiệt độ nước.", "Nhiệt độ cơ thể cá thay đổi ngược lại với chiều thay đổi của nước giúp cho thân nhiệt của cá luôn ổn định", "Nhiệt độ cơ thể cá ổn định điều hoà luôn không đổi.", "Nhiệt độ cơ thể cá tăng và giảm liên tục, nên giúp cá thích nghi với điều kiện nhiệt độ lạnh âm độ C."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b> <b>Chọn A </b>Cá tuyết là động vật biến nhiệt nên nhiệt độ cơ thể cá thay đổi theo môi trường, khi nhiệt độ nước tăng thì nhiệt độ cơ thể cá cũng tăng."}, {"question": "Giải thích nào sau đây đúng về sự thích nghi của loài cá tuyết?", "choices": ["Khi nhiệt độ thấp, độ nhớt của máu tăng, mất tế bào hồng cầu giúp điều hòa lại dòng chảy của máu.", "Khi nhiệt độ thấp, độ nhớt của máu giảm, mất tế bào hồng cầu giúp điều hòa lại dòng chảy của máu.", "Khi nhiệt độ tăng, độ nhớt của máu tăng, mất tế bào hồng cầu giúp điều hòa lại dòng chảy của máu", "Độ nhớt của máu không chịu ảnh hưởng của nhiệt độ, mất tế bào hồng cầu giúp điều hòa lại dòng chảy của máu."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b> <b> Chọn A</b>. Để sinh tồn ở vùng nước băng giá đó, cá tuyết Nam Cực đã tiến hóa để loại bỏ hồng cầu (là tế bào quan trọng trong việc trao đổi chất). Việc này giúp máu loãng hơn (giảm độ nhớt so với khi có hồng cầu), từ đó giúp máu lưu thông (điều hòa dòng chảy) dễ dàng hơn mà không cần tốn quá nhiều năng lượng từ tim.<br><b>B sai:</b> Vì thực tế vật lý là nhiệt độ thấp làm độ nhớt tăng (chất lỏng đặc lại), không phải giảm.<br><b>C sai:</b> Bài đọc xác định cá sống ở vùng Nam Cực lạnh giá, nên giải thích dựa trên việc &quot;nhiệt độ tăng&quot; là không phù hợp với thực tế của loài này.<br><b>D sai:</b> Độ nhớt của mọi chất lỏng (bao gồm cả máu) đều chịu ảnh hưởng mạnh mẽ của nhiệt độ."}, {"question": "Tại sao việc mất hồng cầu lại được coi là một đặc điểm &#x27;thích nghi&#x27; thay vi là một &#x27;đột biến có hại&#x27; đối với cá tuyết sống ở nhiệt độ <span class=\"ct\">−2°C</span> ?", "choices": ["Vì trong môi trường lạnh, hồng cầu không còn khả năng liên kết với Oxy.", "Vì mất hồng cầu giúp cơ thể cá trở nên trong suốt, dễ dàng lẩn trốn kẻ thù.", "Vì nó giúp giảm độ nhớt của máu, giảm bớt gánh nặng cho tim khi bơm máu trong môi trường lạnh.", "Vì hồng cầu sẽ bị đóng băng và vỡ ra khi nhiệt độ xuống dưới <span class=\"ct\">0°C</span>."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b><br><b>A (Sai):</b> Hemoglobin vẫn liên kết được với <span class=\"ct\">O<sub>2</sub></span> ở nhiệt độ thấp, nhưng do nước lạnh đã quá giàu <span class=\"ct\">O<sub>2</sub></span> nên không cần đến nó nữa.<br><b>B (Sai):</b> Cá vùng cực có chất chống đông trong máu nên hồng cầu không bị vỡ do đóng băng.<br><b>C (Đúng):</b> Nhiệt độ thấp <span class=\"ct\">→</span> Máu đặc lại (tăng độ nhớt). Loại bỏ hồng cầu giúp máu loãng hơn, giúp tim bơm máu dễ dàng, không bị quá tải.<br><b>D (Sai):</b> Trong suốt chỉ là &quot;tác dụng phụ&quot;, không phải lý do chính để cá đánh đổi cả hệ thống vận chuyển oxy."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>Năm 2018, Việt Nam đón gần 15,5 triệu lượt khách quốc tế, tăng 19,9% so với năm 2017. Lượng khách quốc tế đến từ 10 thị trường nguồn hàng đầu đạt 12.861.000 lượt, chiếm 83% tổng lượng khách quốc tế đến Việt Nam năm 2018.<br>Lượng khách du lịch nội địa đạt khoảng 80 triệu lượt, tăng 9% so với năm 2017, trong đó có khoảng 38,6 triệu lượt khách có sử dụng dịch vụ lưu trú.<br><img class=\"anh-de\" src=\"data/anh/l13/8ed703a5549bbd3d.png\" alt=\"\" style=\"width:16px;height:13px;vertical-align:middle\">Tổng thu từ khách du lịch năm 2018 đạt 637 nghìn tỷ đồng (tăng 17,7% so với năm 2017). Trong đó tổng thu từ du lịch quốc tế đạt 383 nghìn tỷ đồng (chiếm 60,1%), tổng thu từ du lịch nội địa đạt 254 nghìn tỷ đồng (chiếm 39,9%).<br>Theo đề án “Cơ cấu lại ngành du lịch đáp ứng yêu cầu phát triển thành ngành kinh tế mũi nhọn”, đã được Chính phủ phê duyệt, Việt Nam phấn đấu đến năm 2025 là quốc gia có ngành du lịch phát triển hàng đầu Đông Nam Á, đón và phục vụ 30 - 32 triệu lượt khách du lịch quốc tế, trên 130 triệu lượt khách du lịch nội địa, với tổng thu từ khách du lịch đạt 45 tỷ USD; giá trị xuất khẩu thông qua du lịch đạt 27 tỷ USD; ngành du lịch đóng góp trên 10% GDP và tạo ra 6 triệu việc làm, trong đó có 2 triệu việc làm trực tiếp, với 70% được đào tạo, bồi dưỡng về nghiệp vụ và kỹ năng du lịch.<br>Mục tiêu tổng quát đến năm 2030, du lịch Việt Nam thực sự là ngành kinh tế mũi nhọn, có sức cạnh tranh cao. Việt Nam trở thành điểm đến đặc biệt hấp dẫn, thuộc nhóm quốc gia phát triển du lịch hàng đầu khu vực Đông Nam Á. Đến năm 2050, du lịch Việt Nam trở thành điểm đến có giá trị nổi bật toàn cầu, thuộc nhóm quốc gia phát triển du lịch hàng đầu khu vực châu Á - Thái Bình Dương.<br>(Nguồn: Tổng cục du lịch Việt Nam, website:<i>www.vietnamtourism.gov.vn</i>)", "cauHoi": [{"question": "Cho biết lượng khách du lịch nội địa chiếm khoảng bao nhiêu phần trăm trong tổng lượt khách du lịch quốc tế và nội địa ở nước ta năm 2018?", "choices": ["83,8%", "83%", "85%", "85,7%"], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b><br>Đáp án <b>A</b>. (Tổng khách: 15,5 + 80 = 95,5 triệu; % Nội địa: <span class=\"ct\">80/95,5 × 100 ≈ 83,8%</span>)."}, {"question": "Mục tiêu của ngành du lịch Việt Nam đến năm 2025 là", "choices": ["Du lịch Việt Nam thực sự là ngành kinh tế mũi nhọn.", "Việt Nam trở thành quốc gia có ngành du lịch phát triển nhất Đông Nam Á.", "Việt Nam trở thành quốc gia có ngành du lịch phát triển hàng đầu Đông Nam Á.", "Việt Nam trở thành quốc giá có ngành du lịch phát triển hàng đầu khu vực châu Á - Thái Bình Dương."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b><br><b>Câu 113: Chọn C</b> (Dựa vào đoạn 3: Mục tiêu 2025 là trở thành quốc gia phát triển <b>&quot;hàng đầu&quot;</b> Đông Nam Á)."}, {"question": "Biện pháp tổng thể để đưa du lịch nước ta trở thành ngành kinh tế mũi nhọn phát triển hàng đầu Đông Nam Á là", "choices": ["Thu hút nhiều nguồn vốn đầu tư trong và ngoài nước", "Tái cơ cấu lại ngành du lịch", "Đầu tư cơ sở hạ tầng, đặc biệt là giao thông vận tải.", "Nâng cấp, sửa chữa và khai thác mới nhiều điểm du lịch hấp dẫn"], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 114: Chọn B</b> (Dựa vào tên đề án ở đoạn 3: <b>&quot;Cơ cấu lại ngành du lịch&quot;</b> là biện pháp then chốt để đạt được các mục tiêu đề ra)."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117 </b><br>Từ ngày 25/4 đến 26/6/1945, đại biểu 50 nước họp tại Xan Phranxico (Mĩ) thông qua Hiến chương và thành lập Liên hợp quốc (LHQ). Đây là văn kiện quan trọng nhất, xác lập các mục tiêu và nguyên tắc hoạt động của tổ chức.<br>Mục đích: Duy trì hòa bình và an ninh thế giới; phát triển quan hệ hữu nghị và hợp tác quốc tế.<br>Nguyên tắc chủ đạo: Bình đẳng chủ quyền; Tôn trọng toàn vẹn lãnh thổ; Không can thiệp nội bộ; Giải quyết tranh chấp bằng biện pháp hòa bình; Sự nhất trí giữa 5 nước lớn (Liên Xô, Mĩ, Anh, Pháp, Trung Quốc).<br>Bộ máy: Gồm 6 cơ quan chính. Trong đó, Đại hội đồng gồm tất cả thành viên có quyền bình đẳng. Hội đồng Bảo an là cơ quan trọng yếu nhất trong duy trì hòa bình, mọi quyết định phải được sự nhất trí của 5 nước Ủy viên thường trực. Ban Thư kí là cơ quan hành chính, đứng đầu là Tổng thư kí.<br>Trong hơn nửa thế kỉ, LHQ đã trở thành diễn đàn quốc tế lớn nhất, góp phần hòa giải xung đột và giúp đỡ các dân tộc phát triển kinh tế, y tế, giáo dục.", "cauHoi": [{"question": "Hiến chương của Liên hợp quốc được thông qua tại hội nghị nào?", "choices": ["Hội nghị Ianta.", "Hội nghị Xan Phranxico.", "Hội nghị Pốtxđam.", "Hội nghị Pari."], "correctIndex": 1, "explain": "<b>Câu 115.</b> <b>- Chọn B:</b> Theo bài đọc, hội nghị tại Xan Phranxico (1945) là nơi 50 nước thảo luận và thông qua bản Hiến chương."}, {"question": "Cơ quan nào của Liên hợp quốc đóng vai trò là cơ quan chính trị quan trọng nhất, chịu trách nhiệm duy trì hòa bình và an ninh thế giới?", "choices": ["Đại hội đồng.", "Hội đồng Bảo an.", "Tòa án Quốc tế.", "Hội đồng Quản thác."], "correctIndex": 1, "explain": "<b>Câu 116.</b> <b>- Chọn B:</b> Bài đọc nêu rõ Hội đồng Bảo an giữ vai trò trọng yếu nhất vì mọi quyết định về an ninh thế giới đều do cơ quan này thông qua (với sự đồng thuận của 5 nước lớn)."}, {"question": "Việt Nam có thể vận dụng nguyên tắc nào của Liên hợp quốc trong cuộc đấu tranh bảo vệ chủ quyền biển đảo hiện nay?", "choices": ["Bình đẳng chủ quyền giữa các quốc gia và quyền tự quyết của các dân tộc.", "Tôn trọng toàn vẹn lãnh thổ và độc lập chính trị của tất cả các nước.", "Chung sống hòa bình và sự nhất trí của 5 nước lớn.", "Giải quyết các tranh chấp quốc tế bằng biện pháp hòa bình."], "correctIndex": 3, "explain": "<b>Câu 117.</b> <b>- Chọn D:</b> Đây là nguyên tắc cốt lõi giúp Việt Nam đấu tranh pháp lý, ngoại giao để bảo vệ chủ quyền mà không gây ra xung đột vũ trang."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>Anh Hùng làm việc tại một công ty sản xuất vải, còn vợ anh, chị Mai, là một kế toán cho công ty. Gần đây, anh Hùng nhận thấy một doanh nghiệp trong khu phố có hành vi xả thải gây ô nhiễm môi trường. Anh đã chụp ảnh và quay video để tố cáo hành vi vi phạm này. Chị Mai đang tiến hành làm hồ sơ khai thuế cho công ty của chị theo quy định của pháp luật.", "cauHoi": [{"question": "Hành động của anh Hùng khi tố cáo hành vi xả thải ô nhiễm của doanh nghiệp thể hiện quyền nào sau đây của công dân?", "choices": ["Quyền bầu cử.", "Quyền kinh doanh.", "Quyền tố cáo.", "Quyền tự do ngôn luận."], "correctIndex": 2, "explain": "<b>Câu 118: C. Quyền tố cáo.</b><br><b>Giải thích:</b> Quyền tố cáo là quyền của công dân báo cho cơ quan, tổ chức, cá nhân có thẩm quyền biết về hành vi vi phạm pháp luật của bất cứ cơ quan, tổ chức, cá nhân nào gây thiệt hại hoặc đe dọa gây thiệt hại đến lợi ích của Nhà nước, quyền và lợi ích hợp pháp của công dân, cơ quan, tổ chức. Việc anh Hùng báo cáo hành vi xả thải gây ô nhiễm là thực hiện quyền này."}, {"question": "Việc anh Hùng và chị Mai đều có quyền và nghĩa vụ tham gia vào các hoạt động kinh tế và xã hội, không bị phân biệt vì giới tính, thể hiện nguyên tắc nào dưới đây của pháp luật Việt Nam?", "choices": ["Công dân bình đẳng trước pháp luật", "Quyền tự do ngôn luận", "Quyền và nghĩa vụ về kinh doanh", "Quyền và nghĩa vụ về hôn nhân"], "correctIndex": 0, "explain": "<b>Câu 119: A. Công dân bình đẳng trước pháp luật.</b><br><b>Giải thích:</b> Nguyên tắc này xác định mọi công dân (không phân biệt giới tính, địa vị, nghề nghiệp...) đều được hưởng quyền và phải thực hiện nghĩa vụ theo quy định của pháp luật. Việc cả anh Hùng và chị Mai đều có quyền/nghĩa vụ tham gia hoạt động kinh tế - xã hội mà không bị phân biệt đối xử chính là biểu hiện của sự bình đẳng."}, {"question": "Loại thuế mà công ty chị Mai nộp là loại thuế nào sau đây?", "choices": ["Thuế gián thu.", "Thuế tiêu thụ đặc biệt.", "Thuế trực thu.", "Thuế giá trị gia tăng."], "correctIndex": 2, "explain": "<b>Câu 120: C. Thuế trực thu.</b><br><b>Giải thích:</b> Việc chị Mai làm hồ sơ khai thuế cho công ty thường bao gồm Thuế thu nhập doanh nghiệp (loại thuế đánh trực tiếp vào lợi nhuận của đơn vị kinh doanh). Đây là loại thuế trực thu vì người nộp thuế cũng đồng thời là người chịu thuế, không chuyển tải gánh nặng thuế sang người khác."}], "khongXaoTron": true}]};
